const {withAuth}=require('../../../../../middleware/auth'); const {getSiteById}=require('../../../../../models/Site'); const {listEnv,setEnv}=require('../../../../../models/EnvironmentVariable');
export default withAuth(async(req,res)=>{if(!await getSiteById(req.query.id,req.user.userId))return res.status(404).json({error:'Site not found'});if(req.method==='GET')return res.json({variables:await listEnv(req.query.id)});if(req.method==='POST'){const {key,value}=req.body||{};if(!/^[A-Z_][A-Z0-9_]*$/.test(key||'')||typeof value!=='string')return res.status(400).json({error:'Invalid environment variable'});return res.status(201).json(await setEnv(req.query.id,key,value))}return res.status(405).json({error:'Method not allowed'})});